import type { ThumbnailCue, ThumbnailTrack } from "../../core/types.js";

/** Finds the thumbnail cue covering a timestamp. */
export function findThumbnailAt(track: ThumbnailTrack, time: number): ThumbnailCue | null {
  for (const cue of track.cues) {
    if (time >= cue.startTime && time < cue.endTime) {
      return cue;
    }
  }

  return null;
}

/** Returns the image URL for a timestamp, or null when no cue matches. */
export function thumbnailUrlAt(track: ThumbnailTrack, time: number): string | null {
  return findThumbnailAt(track, time)?.url ?? null;
}

/** Clamps a preview width to the thumbnail's intrinsic size. */
export function thumbnailWidth(cue: ThumbnailCue, maxWidth: number): number {
  return Math.min(cue.width ?? maxWidth, maxWidth);
}
